<?php
require '../config/database.php'; require '../includes/functions.php'; require_admin();
$stats = [
 'rooms'=>(int)$pdo->query("SELECT COUNT(*) FROM rooms")->fetchColumn(),
 'available'=>(int)$pdo->query("SELECT COUNT(*) FROM rooms r WHERE r.status='available' AND NOT EXISTS (SELECT 1 FROM bookings b WHERE b.room_id=r.id AND b.status IN ('pending','confirmed') AND b.check_in < DATE_ADD(CURDATE(), INTERVAL 1 DAY) AND b.check_out > CURDATE())")->fetchColumn(),
 'bookings'=>(int)$pdo->query("SELECT COUNT(*) FROM bookings")->fetchColumn(),
 'pending'=>(int)$pdo->query("SELECT COUNT(*) FROM bookings WHERE status='pending'")->fetchColumn(),
 'customers'=>(int)$pdo->query("SELECT COUNT(*) FROM users WHERE role='customer'")->fetchColumn(),
 'staff'=>(int)$pdo->query("SELECT COUNT(*) FROM users WHERE role='staff'")->fetchColumn(),
 'users'=>(int)$pdo->query("SELECT COUNT(*) FROM users")->fetchColumn(),
 'revenue'=>(float)$pdo->query("SELECT COALESCE(SUM(total_amount),0) FROM bookings WHERE status IN('confirmed','completed')")->fetchColumn()
];
$recent=$pdo->query("SELECT b.*,u.name guest,r.name room_name FROM bookings b JOIN users u ON u.id=b.user_id JOIN rooms r ON r.id=b.room_id ORDER BY CASE WHEN b.status='pending' THEN 0 ELSE 1 END,b.created_at DESC LIMIT 8")->fetchAll();
$activeGuests=$pdo->query("SELECT b.id,b.reference_no,b.check_out,b.guests,u.name guest,u.email,r.name room_name FROM bookings b JOIN users u ON u.id=b.user_id JOIN rooms r ON r.id=b.room_id WHERE b.status='confirmed' AND b.check_in<=CURDATE() AND b.check_out>CURDATE() ORDER BY b.check_out ASC")->fetchAll();
$page_title='Admin Overview'; include '../includes/header.php'; ?>
